   <main className="workspace-center" data-motion-surface="kb-workspace" style={{viewTransitionName:'kb-workspace'}} onDragOver={e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();setDropActive(true);}}} onDragLeave={()=>setDropActive(false)} onDrop={e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();setDropActive(false);run(async()=>{const reply=await window.kbDesktop.importDrop([...e.dataTransfer.files]);if(!reply.ok)throw Object.assign(Error(reply.error.message),{code:reply.error.code});if(reply.value.length){setFormParent('90-收件箱');showDialog({type:'import',files:reply.value});}});}}>{section==='workspace'?<WorkspaceArea onQuickOpen={()=>{setQuickQuery('');showDialog({type:'quick'});}} panes={panes} renderPane={paneView} onDropTab={(drag,target)=>viewChange(()=>{workspace.drop(drag,target);setSelected(drag.path);},{kind:'layout'})} onOpenFile={(path,target)=>run(()=>dropFile(path,target))} onResize={workspace.resize} onLimit={()=>notify('最多四个预览栏，请拖到已有栏的中间合并标签')}/>:pageContent()}{dropActive?<div className="drop-target">松开以导入文件副本</div>:null}</main>
