   {dialog.type==='operation'?<><p className="subtitle">{dialog.file?.path??'在授权目录中创建，不覆盖同名资料。'}</p>{(['create','mkdir','move'].includes(formKind)||formKind==='restore'&&dialog.editDestination)?<><Field label={formKind==='mkdir'?'文件夹名称':'文件名称'} value={formName} onChange={v=>{setFormName(v);setPlan(null);}}/><Field label="所在目录（库内相对路径）" value={formParent} onChange={v=>{setFormParent(v);setPlan(null);}}/></>:<Banner>{formKind==='trash'?(dialog.file?.type==='directory'?'此文件夹及其中的文件将移入回收站，可以恢复。':'此文件将移入回收站，可以恢复。'):formKind==='restore'?'将恢复到原位置；同名资料不会被覆盖。':'永久删除后无法通过回收站恢复。'}</Banner>}{formKind==='restore'?<button className="restore-destination" onClick={()=>setDialog(d=>({...d!,editDestination:!d?.editDestination}))}>{dialog.editDestination?'使用当前恢复位置':'更改恢复位置'}</button>:null}{plan&&!['trash','restore','purge'].includes(formKind)?<Banner>预览已通过。{plan.linkUpdates?'将更新 '+plan.linkUpdates+' 个明确引用。':''}{plan.unresolvedLinks?.length?'另有 '+plan.unresolvedLinks.length+' 处短名链接需要人工核对。':''}</Banner>:null}<div className="row-actions"><button onClick={closeDialog} disabled={busy}>取消</button>{['trash','restore','purge'].includes(formKind)?<><button disabled={busy} onClick={()=>setDialog(d=>({...d!,preview:!d?.preview}))}><FileSearch size={15}/>{dialog.preview?'收起文件预览':'预览文件'}</button><button className={formKind==='purge'?'danger':'primary'} disabled={busy} onClick={()=>void dialogAction(async()=>commitOperation(await planOperation()))}>{busy?'正在处理…':formKind==='restore'?'确认恢复':formKind==='purge'?'确认永久删除':'确认移入回收站'}</button></>:!plan?<button className="primary" disabled={busy} onClick={()=>void dialogAction(planOperation)}>检查并预览</button>:<button className="primary" disabled={busy} onClick={()=>void dialogAction(()=>commitOperation())}>{busy?'正在提交…':formKind==='create'?'创建并打开':formKind==='mkdir'?'创建文件夹':'确认移动'}</button>}</div></>:null}
   {dialog.type==='conflict'?<><p>你的输入已保留，请比较后选择处理方式。不会自动覆盖任一版本。</p><div className="compare"><section><h3>磁盘版本</h3><pre>{dialog.disk.text}</pre></section><section><h3>你的草稿</h3><pre>{docs[dialog.path]?.text}</pre></section></div><div className="row-actions"><button className="primary" onClick={()=>operation('create',undefined,docs[dialog.path]?.text)}>草稿另存为副本</button><button onClick={()=>run(async()=>{const disk=dialog.disk;setDocs(v=>({...v,[dialog.path]:{...v[dialog.path],text:disk.text,savedText:disk.text,revision:disk.revision,preview:disk.preview??v[dialog.path].preview,dirty:false,external:false}}));await api('drafts',{remove:dialog.path});closeDialog();})}>采用磁盘版本</button><button onClick={closeDialog}>继续编辑与合并</button></div></>:null}
   {dialog.type==='unsaved'?<><p>以下文件有未保存的更改。可以保存到原文件、保留为本地草稿，或放弃更改后关闭。</p>{Object.values(docs).filter(d=>d.dirty).map(d=><div className="list-line" key={d.path}>{d.path}<span>未保存</span></div>)}<div className="row-actions"><button className="primary" onClick={()=>void dialogAction(saveAndClose)} disabled={busy}>保存更改并关闭</button><button onClick={()=>void dialogAction(keepAndClose)} disabled={busy}>保留草稿并关闭</button><button className="danger-text" onClick={()=>void dialogAction(discardAndClose)} disabled={busy}>不保留更改并关闭</button><button onClick={closeDialog} disabled={busy}>取消关闭</button></div></>:null}
